namespace RestaurantSaaS.Domain.Common;

/// <summary>
/// Base of every table: Guid key (generated by the application, so offline clients can create ids),
/// audit columns, soft delete and a concurrency token. See Database Schema, Section 1.
/// </summary>
public abstract class BaseEntity
{
    public Guid Id { get; protected set; } = Guid.CreateVersion7();

    public DateTime CreatedAt { get; set; }

    public Guid? CreatedBy { get; set; }

    public DateTime UpdatedAt { get; set; }

    public Guid? UpdatedBy { get; set; }

    public bool IsDeleted { get; set; }

    public DateTime? DeletedAt { get; set; }

    public Guid? DeletedBy { get; set; }

    /// <summary>Concurrency token (SQL Server rowversion). Ignored on providers without row versions.</summary>
    public byte[] RowVersion { get; set; } = [];
}
